-- 2026-09-14 persisted active clock for classic ticker receive training.
SET @ddl = (SELECT IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='t_ticker_tape_train' AND column_name='protocol_version')=0,'ALTER TABLE `t_ticker_tape_train` ADD COLUMN `protocol_version` int NULL','DO 0')); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='t_ticker_tape_train' AND column_name='active_since')=0,'ALTER TABLE `t_ticker_tape_train` ADD COLUMN `active_since` datetime(6) NULL','DO 0')); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='t_ticker_tape_train' AND column_name='accumulated_active_millis')=0,'ALTER TABLE `t_ticker_tape_train` ADD COLUMN `accumulated_active_millis` bigint NULL','DO 0')); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
